//! `client-config.json`: the only configuration the web app is built with. Public keys and what is
//! derived from them; nothing else can be added without a new field here, and a test ties the
//! public keys of the schema to this struct.

use std::collections::BTreeMap;

use schemars::JsonSchema;
use serde::Serialize;

use crate::modules::ModuleStatus;
use crate::settings::{GradingScale, Language, Settings};

#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct ClientConfig {
    /// The Vumlo release the file was generated by.
    pub version: String,
    /// Where the web app reaches the API: `server.public_origin` + `/api/v1`.
    pub api_url: String,
    /// The keys marked `public` in the configuration schema.
    pub public: PublicConfig,
    /// Every optional module of this build line and whether it is on.
    pub modules: BTreeMap<String, ModuleStatus>,
    /// The generated logo, relative to the generated directory. Absent without `institution.logo`.
    pub logo: Option<String>,
}

#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct PublicConfig {
    pub server: PublicServer,
    pub institution: PublicInstitution,
}

#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct PublicServer {
    pub public_origin: String,
}

#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct PublicInstitution {
    pub name: String,
    pub short_name: String,
    pub language: Language,
    /// An IANA zone name, e.g. `Europe/Kyiv`.
    pub time_zone: String,
    pub grading_scale: GradingScale,
}

impl ClientConfig {
    pub fn new(settings: &Settings, version: &str, logo: Option<String>) -> Self {
        let institution = &settings.institution;
        Self {
            version: version.to_owned(),
            api_url: api_url(settings),
            public: PublicConfig {
                server: PublicServer {
                    public_origin: settings.server.public_origin.clone(),
                },
                institution: PublicInstitution {
                    name: institution.name.clone(),
                    short_name: institution.short_name.clone(),
                    language: institution.language,
                    time_zone: institution.time_zone.name().to_owned(),
                    grading_scale: institution.grading_scale,
                },
            },
            modules: settings.module_state.statuses(),
            logo,
        }
    }
}

/// The API base URL, derived once from `[server].public_origin`.
pub fn api_url(settings: &Settings) -> String {
    format!("{}/api/v1", settings.server.public_origin)
}

#[cfg(test)]
mod tests {
    use serde_json::Value;

    use super::*;
    use crate::schema;
    use crate::tests::{VALID, build};

    fn leaves(value: &Value, prefix: &str, out: &mut Vec<String>) {
        match value {
            Value::Object(map) => {
                for (key, child) in map {
                    let path = if prefix.is_empty() {
                        key.clone()
                    } else {
                        format!("{prefix}.{key}")
                    };
                    leaves(child, &path, out);
                }
            }
            _ => out.push(prefix.to_owned()),
        }
    }

    #[test]
    fn the_public_part_is_exactly_the_keys_marked_public() {
        let settings = build(VALID, &[]).unwrap();
        let client = ClientConfig::new(&settings, "1.2.3", None);
        let mut shown = Vec::new();
        leaves(
            &serde_json::to_value(&client.public).unwrap(),
            "",
            &mut shown,
        );
        shown.sort();
        let mut marked: Vec<String> = schema::public_paths()
            .into_iter()
            .map(str::to_owned)
            .collect();
        marked.sort();
        assert_eq!(shown, marked);
    }

    #[test]
    fn private_and_secret_values_never_reach_the_client_config() {
        let toml = format!(
            "{VALID}\n[auth]\nallowed_domains = [\"sentinel-domain.edu\"]\n\
             [mail]\nfrom = \"sentinel-from@x.edu\"\n[mail.transport]\nkind = \"smtp\"\n\
             host = \"sentinel-host.edu\"\n\
             [modules.dummy]\nenabled = true\nlabel = \"sentinel-label\"\n\
             endpoint = \"https://sentinel-endpoint.edu\"\n"
        );
        let env = [
            (
                "DATABASE_URL",
                "postgres://sentinel-db-user:sentinel-db-pass@h/db",
            ),
            ("VUMLO__MAIL__TRANSPORT__PASSWORD", "sentinel-smtp-password"),
            ("VUMLO_DUMMY_API_KEY", "sentinel-module-key"),
            ("VUMLO__SERVER__CLIENT_IP_HEADER", "sentinel-header"),
        ];
        let settings = crate::tests::build_with(&toml, &env, &["dummy"]).unwrap();
        let client = ClientConfig::new(&settings, "1", Some("logo.png".to_owned()));

        let text = serde_json::to_string(&client).unwrap();

        assert!(!text.contains("sentinel"), "{text}");
        assert!(text.contains("\"dummy\":\"enabled\""), "{text}");
        assert!(text.contains("https://lms.example.edu/api/v1"), "{text}");
    }

    #[test]
    fn every_module_of_the_registry_is_listed_with_its_state() {
        let settings = build(VALID, &[]).unwrap();
        let client = ClientConfig::new(&settings, "1", None);
        let names: Vec<_> = client.modules.keys().map(String::as_str).collect();
        let known: Vec<_> = crate::modules::known_modules()
            .iter()
            .map(|m| m.name)
            .collect();
        assert_eq!(names, known);
        assert!(
            client
                .modules
                .values()
                .all(|s| *s == ModuleStatus::Unavailable)
        );
    }
}
